def mark_chosen_times(apps, schema_editor):
    """`learning.reminder_times` defaults to ["19:00"], so a stored value that differs was picked by the learner."""
    UserPreferences = apps.get_model("accounts", "UserPreferences")
    ReminderState = apps.get_model("accounts", "ReminderState")
    rows = []
    for user_id, data in UserPreferences.objects.values_list("user_id", "data").iterator():
        times = ((data or {}).get("learning") or {}).get("reminder_times")
        if isinstance(times, list) and times and times != ["19:00"]:
            rows.append(ReminderState(user_id=user_id, time_chosen=True))
    ReminderState.objects.bulk_create(rows, batch_size=500, ignore_conflicts=True)


